package com.nutribite.ai.goals.service; import com.nutribite.ai.goals.dto.*; import com.nutribite.ai.goals.entity.NutritionGoal; import com.nutribite.ai.goals.repository.NutritionGoalRepository; import com.nutribite.ai.model.User; import com.nutribite.ai.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional public class GoalServiceImpl implements GoalService {private final UserRepository users; private final NutritionGoalRepository goals; private User user(){String e=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmail(e).orElseThrow(()->new RuntimeException("User not found"));} private GoalResponse map(NutritionGoal x){return GoalResponse.builder().id(x.getId()).targetCalories(x.getTargetCalories()).targetProtein(x.getTargetProtein()).targetCarbs(x.getTargetCarbs()).targetFat(x.getTargetFat()).targetFibre(x.getTargetFibre()).targetWeightKg(x.getTargetWeightKg()).updatedAt(x.getUpdatedAt()).build();} public GoalResponse get(){return goals.findByUser(user()).map(this::map).orElse(GoalResponse.builder().build());} public GoalResponse save(GoalRequest r){User u=user();NutritionGoal x=goals.findByUser(u).orElse(NutritionGoal.builder().user(u).build());x.setTargetCalories(r.getTargetCalories());x.setTargetProtein(r.getTargetProtein());x.setTargetCarbs(r.getTargetCarbs());x.setTargetFat(r.getTargetFat());x.setTargetFibre(r.getTargetFibre());x.setTargetWeightKg(r.getTargetWeightKg());return map(goals.save(x));}}
